BEGIN;
UPDATE messages SET payload=payload||jsonb_build_object('senderRole',CASE WHEN EXISTS(SELECT 1 FROM guardians g WHERE g.school_id=messages.school_id AND g.owner_id=messages.owner_id AND g.student_id=messages.student_id AND g.deleted_at IS NULL AND g.payload->>'canView'='true') THEN 'parent' ELSE COALESCE((SELECT m.role FROM memberships m WHERE m.school_id=messages.school_id AND m.user_id=messages.owner_id AND m.role IN ('teacher','hod','principal','admin') AND m.active=true ORDER BY m.role LIMIT 1),'admin') END,'recipientRole',CASE WHEN EXISTS(SELECT 1 FROM guardians g WHERE g.school_id=messages.school_id AND g.owner_id=(messages.payload->>'recipientUserId')::uuid AND g.student_id=messages.student_id AND g.deleted_at IS NULL AND g.payload->>'canView'='true') THEN 'parent' ELSE COALESCE((SELECT m.role FROM memberships m WHERE m.school_id=messages.school_id AND m.user_id=(messages.payload->>'recipientUserId')::uuid AND m.role IN ('teacher','hod','principal','admin') AND m.active=true ORDER BY m.role LIMIT 1),'admin') END),version=version+1 WHERE NOT(payload ? 'senderRole');
COMMIT;
